(6845964, 1029812, 101256, '<td valign="top">A very effective image if all the branches didn''t mess up the "whole" of the image. Still, pretty good.</td>', 'A very effective image if all the branches didn''t mess up the "whole" of the image. Still, pretty good.', '2012-08-21 17:04:24.000000', NULL, 1),
(6845965, 1029743, 101256, '<td valign="top">Sure is interesting that''s for sure.  I wonder what it is? Good eye and a good capture.</td>', 'Sure is interesting that''s for sure.  I wonder what it is? Good eye and a good capture.', '2012-08-21 17:04:58.000000', NULL, 1),
(6845967, 1029791, 101256, '<td valign="top">Sometimes simple is most effective. This image is simple, elegant and conveys the spirit of the challenge. Well done.</td>', 'Sometimes simple is most effective. This image is simple, elegant and conveys the spirit of the challenge. Well done.', '2012-08-21 17:05:42.000000', NULL, 1),
(6845968, 1029806, 101256, '<td valign="top">I think this image is a little too tall to be truly effective to the viewer. I''m looking at it on a huge monitor and it still doesn''t fit. Might want to keep that in mind. Otherwise, it''s pretty good - makes me dizzy just looking at it.</td>', 'I think this image is a little too tall to be truly effective to the viewer. I''m looking at it on a huge monitor and it still doesn''t fit. Might want to keep that in mind. Otherwise, it''s pretty good - makes me dizzy just looking at it.', '2012-08-21 17:07:01.000000', NULL, 1),
(6845969, 1029803, 101256, '<td valign="top">I like it - a little too cramped, but it works.</td>', 'I like it - a little too cramped, but it works.', '2012-08-21 17:07:45.000000', NULL, 1),
(6845971, 1029702, 101256, '<td valign="top">Good lord - this is just terrific. I really like this a lot. Very effective imagery. Well done.</td>', 'Good lord - this is just terrific. I really like this a lot. Very effective imagery. Well done.', '2012-08-21 17:08:30.000000', NULL, 1),
(6845972, 1029694, 101256, '<td valign="top">Whoa - another terrific image. The blue isn''t over done, just perfect and the excellent focus and DOF control is simply brilliant.  Well done - a favorite from this challenge and hopefully a top ten finish.</td>', 'Whoa - another terrific image. The blue isn''t over done, just perfect and the excellent focus and DOF control is simply brilliant.  Well done - a favorite from this challenge and hopefully a top ten finish.', '2012-08-21 17:10:08.000000', NULL, 1),
(6845973, 1029647, 101256, '<td valign="top">I like this, but there is something about it that is annoying -I can''t put my finger on what it is. Still, a worthy effort.</td>', 'I like this, but there is something about it that is annoying -I can''t put my finger on what it is. Still, a worthy effort.', '2012-08-21 17:10:57.000000', NULL, 1),
(6845974, 1029841, 101256, '<td valign="top">The blue is a little forced and does not look natural at all.</td>', 'The blue is a little forced and does not look natural at all.', '2012-08-21 17:11:51.000000', NULL, 1),
(6845975, 1029324, 101256, '<td valign="top">This is certainly different. Not sure how effective the image is though - it just doesn''t seem to have any context.</td>', 'This is certainly different. Not sure how effective the image is though - it just doesn''t seem to have any context.', '2012-08-21 17:13:05.000000', NULL, 1),
(6845977, 1029804, 101256, '<td valign="top">The blue here is certainly forced, but it does work. Very effective image - simple yet complex at the same time. Nice concept. Well done.</td>', 'The blue here is certainly forced, but it does work. Very effective image - simple yet complex at the same time. Nice concept. Well done.', '2012-08-21 17:14:35.000000', NULL, 1),
(6845978, 1029680, 101256, '<td valign="top">Symmetry is good for imagery and this works very well. Very well captured and connected to the spirit of the challenge. Well done.</td>', 'Symmetry is good for imagery and this works very well. Very well captured and connected to the spirit of the challenge. Well done.', '2012-08-21 17:15:41.000000', NULL, 1),
(6845980, 1029844, 101256, '<td valign="top">There is a depth here that is effectively 3D. Amazing detail and color. Very nicely imaged and captured. Well done.</td>', 'There is a depth here that is effectively 3D. Amazing detail and color. Very nicely imaged and captured. Well done.', '2012-08-21 17:16:47.000000', NULL, 1),
(6845981, 1029186, 101256, '<td valign="top">Er...ok. I guess.</td>', 'Er...ok. I guess.', '2012-08-21 17:17:04.000000', NULL, 1),
